// seed: tests/seed.admin.spec.ts · ПРОД: только просмотр, кнопки вкладки не нажимаются.
// Не-GET блокируются, кроме чтения прав rpc/is_admin (POST-RPC без записи).
import { test, expect } from '@playwright/test';

const SAFE_METHODS = ['GET', 'HEAD', 'OPTIONS'];
const READ_ONLY_RPC = /\/rest\/v1\/rpc\/is_admin$/;

test.use({ storageState: '../auth/admin.json', serviceWorkers: 'block' });

test('Админка «טמפלייטים לתמונות» открывается #c18c9e @desktop @prod-safe', async ({ page }) => {
  await page.route('**/*', (route) => {
    const r = route.request();
    if (SAFE_METHODS.includes(r.method()) || READ_ONLY_RPC.test(r.url().split('?')[0])) return route.fallback();
    return route.abort('blockedbyclient');
  });

  await page.goto('/admin?tab=templates');
  await expect(page.getByRole('heading', { name: 'ניהול - פאנל מנהל' })).toBeVisible({ timeout: 20_000 });
  await expect(page.getByRole('tab', { name: 'טמפלייטים לתמונות' })).toHaveAttribute('aria-selected', 'true');
  for (const name of ['שמור טמפלייט', 'נקה טופס', 'צור תמונה עם AI']) {
    await expect(page.getByRole('button', { name }), `кнопка «${name}»`).toBeVisible();
  }
});
